// Category B — no headless component and no behavior → own everything (no React Aria import).
// (Contract: docs/rules/component-contract.md — sd- prefix, single class, data-*, tokens only)
import type { HTMLAttributes, ReactNode, Ref } from "react";
import "./Badge.css";

type BadgeVariant =
  | "neutral"
  | "primary"
  | "tonal"
  | "strong"
  | "success"
  | "warning"
  | "info"
  | "error"
  | "urgency"
  | "live"
  | "overlay";

type BadgeSize = "small" | "medium";

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * What the badge states (prop-usage-contract.md § Variant, row badge). `tonal` is the brand tint, `strong` the
   * dark solid, the same two words as Button's. `primary` is the brand solid, Button's third word, for
   * a count nested inside a Button ("Filter 3") or a recommendation ribbon over a tile; beside a
   * Button it would read as one, so the attention chip there stays `tonal`. `live` marks something happening now (a stream, a
   * session in progress): the neutral badge with a red dot before its label. The label still carries
   * the meaning ("LIVE"). `overlay` protects a label over media with inverse backing and ink.
   *
   * @default "neutral"
   */
  variant?: BadgeVariant;
  /**
   * Size axis: the box, never the type. Both sizes set `caption-small`, the floor of the caption
   * role, so there is no smaller text to step to. `small` is a 20px box as wide as it is tall at
   * least, so a single-digit count reads round: a count nested inside a small control (FieldButton's
   * count). `medium` is the box its line and padding make, the label beside a heading or a value.
   *
   * @default "medium"
   */
  size?: BadgeSize;
  /**
   * A slot of the categorical palette (1 to 8), for a label that names one member of a set (a sales
   * channel, an order source) told from its siblings by colour. When set it replaces `variant`; the
   * label still carries the meaning.
   */
  category?: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
  /** Optional leading icon. It is treated as decorative and receives `aria-hidden`, so the label
   *  text must carry the meaning. It is set to the badge's caption-small text, so pass `size="1em"`. */
  icon?: ReactNode;
  /** Forwarded to the underlying <span> DOM node. */
  ref?: Ref<HTMLSpanElement>;
}

export function Badge({
  variant = "neutral",
  size = "medium",
  category,
  icon,
  children,
  className,
  ...props
}: BadgeProps) {
  return (
    <span
      {...props}
      data-size={size}
      data-variant={category ? undefined : variant}
      data-category={category}
      // CONTRASTIVE: a Badge labels the text it sits with (a heading, a value, a row name, a step's
      // title, a column's name; token-contract.md's heading-badge row), so it is that pair's
      // subordinate text, one rung below the default. At `medium` it stood as tall as a small Button.
      className={
        className ? `sd-badge sd-type-caption-small ${className}` : "sd-badge sd-type-caption-small"
      }
    >
      {!category && variant === "live" && <span aria-hidden="true" className="sd-badge__dot" />}
      {icon != null && icon !== false && (
        <span aria-hidden="true" className="sd-badge__icon">
          {icon}
        </span>
      )}
      {children}
    </span>
  );
}

/* Badge.css — .sd-badge
   분류 B: 헤드리스 없이 전부 소유. 규칙은 동일 — sd- 프리픽스, 단일 클래스,
   variant 는 data-*, Cmp 토큰만 참조. */
.sd-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-badge-gap);
  padding: var(--sd-badge-padding-block) var(--sd-badge-padding-inline-medium);
  border: var(--sd-badge-border-width) solid transparent;
  border-radius: var(--sd-badge-radius);
  corner-shape: round;
  white-space: nowrap;
}
/* small: a fixed box from the icon ladder, no block inset, and as wide as it is tall at least, so a
   single-digit count is a circle and a longer one a short pill. Centred, since the box can be wider
   than its words. */
.sd-badge[data-size="small"] {
  justify-content: center;
  block-size: var(--sd-badge-height-small);
  min-inline-size: var(--sd-badge-height-small);
  padding: 0 var(--sd-badge-padding-inline-small);
}

.sd-badge[data-variant="neutral"],
.sd-badge[data-variant="live"] {
  background: var(--sd-badge-background-neutral);
  color: var(--sd-badge-foreground-neutral);
  border-color: var(--sd-badge-border-neutral);
}
.sd-badge[data-variant="primary"] {
  background: var(--sd-badge-background-primary);
  color: var(--sd-badge-foreground-primary);
}
.sd-badge[data-variant="tonal"] {
  background: var(--sd-badge-background-tonal);
  color: var(--sd-badge-foreground-tonal);
}
.sd-badge[data-variant="strong"] {
  background: var(--sd-badge-background-strong);
  color: var(--sd-badge-foreground-strong);
}
.sd-badge[data-variant="success"] {
  background: var(--sd-badge-background-success);
  color: var(--sd-badge-foreground-success);
}
.sd-badge[data-variant="warning"] {
  background: var(--sd-badge-background-warning);
  color: var(--sd-badge-foreground-warning);
}
.sd-badge[data-variant="info"] {
  background: var(--sd-badge-background-info);
  color: var(--sd-badge-foreground-info);
}
.sd-badge[data-variant="error"] {
  background: var(--sd-badge-background-error);
  color: var(--sd-badge-foreground-error);
}
.sd-badge[data-variant="urgency"] {
  background: var(--sd-badge-background-urgency);
  color: var(--sd-badge-foreground-urgency);
}

/* A categorical slot fills the chip from the palette with the ink every slot is derived to carry. */
.sd-badge[data-category] {
  color: var(--sd-badge-foreground-category);
}
.sd-badge[data-category="1"] {
  background: var(--sd-badge-background-category-1);
}
.sd-badge[data-category="2"] {
  background: var(--sd-badge-background-category-2);
}
.sd-badge[data-category="3"] {
  background: var(--sd-badge-background-category-3);
}
.sd-badge[data-category="4"] {
  background: var(--sd-badge-background-category-4);
}
.sd-badge[data-category="5"] {
  background: var(--sd-badge-background-category-5);
}
.sd-badge[data-category="6"] {
  background: var(--sd-badge-background-category-6);
}
.sd-badge[data-category="7"] {
  background: var(--sd-badge-background-category-7);
}
.sd-badge[data-category="8"] {
  background: var(--sd-badge-background-category-8);
}

/* Leading icon slot. `inline-flex` so the glyph's own line-height cannot add leading inside a
   chip this small — the box is the glyph. Sized to the icon scale that matches the chip's
   `caption-small` text, so the icon reads as part of the label, not an ornament. */
.sd-badge__icon {
  display: inline-flex;
  flex: 0 0 auto;
  font-size: var(--sd-badge-icon-font-size);
}

/* The live variant's dot: a static mark, never a pulse. A blink that runs past five seconds needs a
   way to pause it (WCAG 2.2.2), and a LIVE badge stays on screen for as long as the thing is live. */
.sd-badge__dot {
  flex: 0 0 auto;
  inline-size: var(--sd-badge-dot-size);
  block-size: var(--sd-badge-dot-size);
  border-radius: var(--sd-badge-dot-radius);
  corner-shape: round;
  background: var(--sd-badge-dot-background);
}

.sd-badge[data-variant="overlay"] {
  background: var(--sd-badge-background-overlay);
  color: var(--sd-badge-foreground-overlay);
  white-space: normal;
}
